function validateAssessment(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  raw = {...raw, options: raw.options ?? []};
  const keys = ['options','decision','information_sufficient','questions','advice','missing_information'];
  if (Object.keys(raw).length !== keys.length || keys.some(k => !Object.prototype.hasOwnProperty.call(raw,k))) return null;
  const strings = (a,max,len) => Array.isArray(a) && a.length <= max && a.every(s => typeof s === 'string' && s.trim() && s.length <= len);
  if (typeof raw.information_sufficient !== 'boolean' || typeof raw.advice !== 'string' || raw.advice.length > 20000 ||
      !strings(raw.options,8,300) || new Set(raw.options).size !== raw.options.length || !strings(raw.questions,5,2000) || !strings(raw.missing_information,10,1000)) return null;
  if (raw.decision === 'ASK_CLARIFICATION') {
    if ((raw.options.length > 0 && raw.questions.length !== 1) || raw.information_sufficient || raw.questions.length === 0 || raw.advice.trim() || raw.missing_information.length === 0) return null;
  } else if (raw.decision === 'PROVIDE_ADVICE') {
    if (raw.options.length || !raw.information_sufficient || raw.questions.length || !raw.advice.trim() || raw.missing_information.length) return null;
  } else return null;
  return raw;
}

const b=$('Strict Route Validator').first().json;
const raw=$json ?? {};
const assessment=raw.error || raw.ok===false ? null : validateAssessment(raw.structuredOutput);
if (!assessment) return {json:{request_id:b.request.request_id,status:'error',requested_capabilities:['hr_consultation'],needs_clarification:null,clarification_question:'',reason_code:'HR_ASSESSMENT_FAILED',errors:[raw.error?'MODEL_UNAVAILABLE':'INVALID_ASSESSMENT_CONTRACT'],hr_consultation:null,artifact_generation:null}};
const needs=assessment.decision==='ASK_CLARIFICATION';
return {json:{request_id:b.request.request_id,status:'awaiting_review',review_required:true,requested_capabilities:['hr_consultation'],needs_clarification:needs,clarification_question:needs?(assessment.options.length ? JSON.stringify({kind:'clarification',question:assessment.questions[0],options:assessment.options}) : assessment.questions.join('\n')):'',decision:assessment.decision,assessment,reason_code:b.route.reason_code,errors:[],hr_consultation:needs?null:assessment.advice,artifact_generation:null}};
